package paasio

import (
	"io"
	"sync"
)

// readCounter implements ReadCounter by wrapping an io.Reader and recording
// the total number of bytes read and the total number of Read() calls.
//
// A single mutex guards both counters so that ReadCount always returns a
// consistent snapshot, even while Read calls are in flight concurrently.
type readCounter struct {
	reader io.Reader
	mu     sync.Mutex
	n      int64
	nops   int
}

// writeCounter implements WriteCounter by wrapping an io.Writer and recording
// the total number of bytes written and the total number of Write() calls.
//
// A single mutex guards both counters so that WriteCount always returns a
// consistent snapshot, even while Write calls are in flight concurrently.
type writeCounter struct {
	writer io.Writer
	mu     sync.Mutex
	n      int64
	nops   int
}

// readWriteCounter implements ReadWriteCounter by combining a readCounter and
// a writeCounter that share the same underlying io.ReadWriter.
type readWriteCounter struct {
	*readCounter
	*writeCounter
}

// NewWriteCounter returns a WriteCounter that wraps writer and reports the
// total number of bytes written and the number of Write() calls.
func NewWriteCounter(writer io.Writer) WriteCounter {
	return &writeCounter{writer: writer}
}

// NewReadCounter returns a ReadCounter that wraps reader and reports the
// total number of bytes read and the number of Read() calls.
func NewReadCounter(reader io.Reader) ReadCounter {
	return &readCounter{reader: reader}
}

// NewReadWriteCounter returns a ReadWriteCounter that wraps readwriter and
// reports IO statistics for both reading and writing.
func NewReadWriteCounter(readwriter io.ReadWriter) ReadWriteCounter {
	return &readWriteCounter{
		readCounter:  &readCounter{reader: readwriter},
		writeCounter: &writeCounter{writer: readwriter},
	}
}

// Read reads from the wrapped reader, records the bytes read and the call,
// and returns the underlying result unchanged.
func (rc *readCounter) Read(p []byte) (int, error) {
	n, err := rc.reader.Read(p)
	rc.mu.Lock()
	rc.n += int64(n)
	rc.nops++
	rc.mu.Unlock()
	return n, err
}

// ReadCount returns the total number of bytes read and the total number of
// Read() calls, read atomically under the same lock.
func (rc *readCounter) ReadCount() (int64, int) {
	rc.mu.Lock()
	defer rc.mu.Unlock()
	return rc.n, rc.nops
}

// Write writes to the wrapped writer, records the bytes written and the call,
// and returns the underlying result unchanged.
func (wc *writeCounter) Write(p []byte) (int, error) {
	n, err := wc.writer.Write(p)
	wc.mu.Lock()
	wc.n += int64(n)
	wc.nops++
	wc.mu.Unlock()
	return n, err
}

// WriteCount returns the total number of bytes written and the total number
// of Write() calls, read atomically under the same lock.
func (wc *writeCounter) WriteCount() (int64, int) {
	wc.mu.Lock()
	defer wc.mu.Unlock()
	return wc.n, wc.nops
}
